"use client";

import { useState, useEffect, useMemo } from "react";
import { usePathname } from "next/navigation";
import Link from "next/link";
import Cookies from "js-cookie";
import { User as UserIcon } from "lucide-react";
import { RightOutlined } from "@ant-design/icons";
import { ThemeProvider } from "@/components/theme-provider";
import Hedaer from "@/components/Hedaer";
import { ModeToggle } from "@/components/mode";

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const [isOpen, setIsOpen] = useState(true);
  const [user, setUser] = useState<any>(null);
  const [mounted, setMounted] = useState(false);

  const hideHeader = pathname === "/login";
  const BASE_URL = process.env.NEXT_PUBLIC_BASE_URL || "http://localhost:7070";

  const pageTitle = useMemo(() => {
    const titles: Record<string, string> = {
      "/": "Boshqaruv Paneli",
      "/menagers": "Menejerlar",
      "/admins": "Adminlar",
      "/teachers": "O'qituvchilar",
      "/students": "Talabalar",
      "/groups": "Guruhlar",
      "/courses": "Kurslar",
      "/payment": "To'lovlar",
      "/settings": "Sozlamalar",
      "/profile": "Profil",
    };
    return titles[pathname] || "CRM Panel";
  }, [pathname]);

  useEffect(() => {
    setMounted(true);
    if (typeof document !== "undefined") {
      document.title = `${pageTitle} | CRM Edu`;
    }
  }, [pageTitle]);

  useEffect(() => {
    const savedUser = Cookies.get("user") || localStorage.getItem("user");
    if (savedUser) {
      try {
        const parsed = JSON.parse(savedUser);
        setUser(parsed.data || parsed);
      } catch (e) {
        console.error("User parsing xatosi");
      }
    }
  }, []);

  if (!mounted)
    return (
      <html lang="uz">
        <body></body>
      </html>
    );

  return (
    <html lang="uz" suppressHydrationWarning>
      <body className="antialiased bg-background text-foreground">
        <ThemeProvider attribute="class" defaultTheme="system" enableSystem>
          <div className="flex h-screen overflow-hidden">
            {!hideHeader && (
              <aside
                className={`transition-all duration-300 border-r shrink-0 ${isOpen ? "w-72" : "w-0 overflow-hidden"}`}
              >
                <Hedaer isOpen={isOpen} />
              </aside>
            )}

            <div className="flex-1 flex flex-col min-w-0">
              {!hideHeader && (
                <header className="flex justify-between items-center border-b p-3 bg-background/80 backdrop-blur-md">
                  <div className="flex items-center gap-4">
                    <button
                      onClick={() => setIsOpen(!isOpen)}
                      className="p-2 rounded-lg hover:bg-accent"
                    >
                      <svg
                        width="20"
                        height="20"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                      >
                        <rect width="18" height="18" x="3" y="3" rx="2" />
                        <path d="M9 3v18" />
                      </svg>
                    </button>
                    <nav className="flex items-center text-sm">
                      <span className="opacity-50">Asosiy</span>
                      <RightOutlined className="mx-2 opacity-30 text-[10px]" />
                      <span className="font-semibold">{pageTitle}</span>
                    </nav>
                  </div>
                  <div className="flex items-center gap-4">
                    <ModeToggle />
                    <Link href="/profile" className="flex items-center gap-2">
                      <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center overflow-hidden border">
                        {user?.image ? (
                          <img
                            src={`${BASE_URL}/${user.image}`}
                            className="w-full h-full object-cover"
                          />
                        ) : (
                          <UserIcon size={16} />
                        )}
                      </div>
                    </Link>
                  </div>
                </header>
              )}
              <main className="flex-1 overflow-y-auto p-6">{children}</main>
            </div>
          </div>
        </ThemeProvider>
      </body>
    </html>
  );
}
